    function _setBtnState(text, bg, disabled) {
      if (!btn) return;
      btn.disabled = !!disabled;
      btn.textContent = text;
      if (bg !== undefined) btn.style.background = bg;
    }
    _setBtnState("⏳ Starting…", "linear-gradient(180deg,#f59e0b,#d97706)", true);
    return _publishTemplate(t, {
      onProgress: function (phase) {
        _setBtnState("⏳ " + phase, "linear-gradient(180deg,#f59e0b,#d97706)", true);
      },
    }).then(function (r) {
      _setBtnState("✅ Pushed", "linear-gradient(180deg,#16a34a,#15803d)", true);
      _toast("✅ Pushed '" + (t.name || id) + "' · " + Math.round(r.size / 1024) + " KB · " + _absoluteDate(r.publishedAt), "ok");
      // Hold success state for ~1.5s before restoring to plain Push,
      // then trigger a refresh so the row's badges/timestamps update.
      setTimeout(function () {
        _setBtnState("📤 Push", "", false);
        if (btn) btn.style.background = "linear-gradient(180deg,#16a34a,#15803d)";
        _refresh();
      }, 1500);
    }).catch(function (e) {
      _setBtnState("❌ Failed", "linear-gradient(180deg,#dc2626,#991b1b)", true);
      _toast("Push failed: " + (e && e.message), "err");
      // Hold failure state for 3s so the user notices, then restore.
      setTimeout(function () {
        _setBtnState("📤 Push", "", false);
        if (btn) btn.style.background = "linear-gradient(180deg,#16a34a,#15803d)";
      }, 3000);
    });
  }


  // ── Tile + dispatch entry ─────────────────────────────────────────
  eli.register({
    tile: { app_template_manager: _open },
    template_manager: {
      open: _open,
      publish: function (id) {
        return _loadAllTemplates().then(function (rows) {
          var t = rows.find(function (r) { return r.id === id; });
          if (!t) throw new Error("Template not found: " + id);
          return _publishTemplate(t);
        });
      },
    },
  });
  eli.log.event("tool", "template_manager_init", { email: userEmail });
}
